SELECT c.CATEGORY_ID, c.CATEGORY_CODE, c.CATEGORY_NAME, c.PARENT_ID, c.DEPRECIATION_METHOD, c.USEFUL_LIFE, c.RESIDUAL_RATE, c.SORT_ORDER, c.REMARK, c.TENANT_ID, c.CREATE_BY, c.CREATE_TIME, c.UPDATE_BY, c.UPDATE_TIME, c.IS_DELETED, p.CATEGORY_NAME AS parentName FROM TBL_FIXED_ASSET_CATEGORY c LEFT JOIN TBL_FIXED_ASSET_CATEGORY p ON c.PARENT_ID = p.CATEGORY_ID AND p.IS_DELETED = 0 WHERE c.IS_DELETED = 0
AND c.TENANT_ID = #{tenantId}
ORDER BY c.SORT_ORDER ASC, c.CREATE_TIME ASC
